    // In a supplier category/annotation, "English Hindi Dubbed" identifies the
    // Hindi dub of an English catalogue. It is not a two-track declaration.
    // Only an adjacent pair of known language words followed by an explicit
    // dub marker is collapsed. Lists ("English / Hindi"), title prose, regional
    // bundles and contradictions with another field keep their usual guards.
    function normalizeProviderDubbedCategory(value) {
        return value.replace(/(^|[|:])\s*([\p{L}\p{M}]{4,30})\s+([\p{L}\p{M}]{4,30})\s+(dubbed|dub)\s*$/iu,
            (match, boundary, original, dubbed, marker) => {
                const alias = token => {
                    const key = stripDiacritics(token).normalize('NFC').toLowerCase();
                    return Object.prototype.hasOwnProperty.call(VERSION_PROVIDER_LANGUAGE_TAGS, key)
                        ? VERSION_PROVIDER_LANGUAGE_TAGS[key] : null;
                };
                const from = alias(original), to = alias(dubbed);
                return from && to && from !== 'nordic' && to !== 'nordic'
                    ? `${boundary} ${dubbed} ${marker}` : match;
            });
    }

    // Exact supplier category labels from the September residual-language audit.
    // These are declarations, not observed tracks or country-to-language aliases.
    // Keep the full labels: arbitrary prose, subtitle suffixes and market bundles
    // must not acquire an audio language by matching a word inside a category.
    const VERSION_PROVIDER_AUDITED_CATEGORIES = {
        'FR I BOX OFFICE & ULTRA 4K': 'FR | BOX OFFICE & ULTRA 4K',
        'أفلام فرنسية': 'FRENCH MOVIES',
        'Séries ARABES': 'ARABIC SERIES',
        'مسلسلات عربية | SERIES ARABES': 'ARABIC SERIES',
        'افلام عربية | FILMS ARABES': 'ARABIC MOVIES',
        'أفلام عربية قديمة | ANCIENS FILMS ARABES': 'ARABIC MOVIES',
        'مسلسلات تركية مدبلجة عربي | Turkish Series Arabic Dub': 'ARABIC DUB',
        'Séries DUB-AR': 'ARABIC DUB',
        '4K | أفلام عربية': 'ARABIC MOVIES',
        'يعرض الآن عربي': 'ARABIC SERIES',
        'SÉRIES TURK': 'TURKISH SERIES'
    };

    function normalizeProviderAuditedCategory(value) {
        const key = value.trim().replace(/\s+/g, ' ');
        if (Object.prototype.hasOwnProperty.call(VERSION_PROVIDER_AUDITED_CATEGORIES, key)) {
            return VERSION_PROVIDER_AUDITED_CATEGORIES[key];
        }
        // A category delimiter is not title prose. Only known uppercase codes
        // can introduce CODE I SECTION; keep the remainder for conflict guards.
        value = value.replace(/^\s*([A-Z]{2,3})\s+I\s+(.+)$/, (match, code, section) =>
            VERSION_PROVIDER_LANGUAGE_TAGS[code.toLowerCase()] ? `${code} | ${section}` : match);
        value = value.replace(/^\s*MOVIES\s+([A-Z]{2,3})(\s+(?:\d{4}(?:-\d{4})?|CLASSICS\s*&\s*RARITIES))?\s*$/,
            (match, code, tail = '') => VERSION_PROVIDER_LANGUAGE_TAGS[code.toLowerCase()] ? `${code} | MOVIES${tail}` : match);
        // Preserve a regional label, never invent a particular Balkan language.
        return value.replace(/^\s*EX-YU(?=\s*[|:]|\s*$)/i, 'EXYU');
    }
    export function providerCatalogLanguage(item = {}) {
        let category = normalizeProviderAuditedCategory(String(item.category_name || item.categoryName || item.metadata?.categoryName || item.metadata?.category_name || '').replace(BAR_SEPARATORS, ' | ').slice(0, 1000)
            // A complete category label can delimit a leading tag with a space.
            // Do not extend this to prose such as "NO ADS" or "FILMES DE AÇÃO".
            .replace(/^\s*([A-Z]{2,3})\s+(MOVIES|FILMS|SERIES)\s*$/, '$1 | $2'));
        // In this audited supplier category NL denotes the market, while HINDI
        // is the language declaration. Do not generalize to other code/name pairs.
        const nlHindiCategory = /^\s*NL\s*\|\s*HINDI\s*$/i.test(category);
        // Local M3U/Xtream inventories may retain the raw label only as `name`.
        // A source/category context is required before treating it as a supplier label.
        const providerContext = category || item.sourceId || item.source_id;
        let raw = String(item.raw_title || item.rawTitle || (providerContext ? item.name || item.title : '') || '')
            .replace(BAR_SEPARATORS, ' | ').slice(0, 2000);
        // Role-aware supplier grammars from the residual audit. These do not
        // weaken generic subtitle/conflict guards: only the complete category
        // and its matching bare prefix may assign the destination of a dub.
        const categoryKey = category.trim().replace(/\s+/g, ' ');
        // On these exact English shelves, a final Arabic "subtitled" marker
        // does not erase the separately declared English audio. Strip it only
        // in this local parsing copy, before suffix inspection so conflicting
        // annotations such as (French) remain visible to every existing guard.
        if (['MOVIES - ENGLISH 2024',
            'مسلسلات إنجليزية 2022 | English Series 2022',
            'مسلسلات إنجليزية 2023 | English Series 2023',
            'مسلسلات إنجليزية 2024 | English Series 2024',
            'مسلسلات إنجليزية 2025 | English Series 2025'].includes(categoryKey)) {
            raw = raw.replace(/\s+مترجم\s*$/u, '');
        }
        const barePrefix = code => new RegExp(`^\\s*${code}(?=\\s*[-–—]\\s+|\\s+[-–—]\\s*|\\s*[|:])`);
        // Exact audited shelves declare Turkish audio and Arabic subtitles.
        // Change only local parser inputs; keep all independent audio conflicts
        // and exact-file observations intact. This is not an AR/TR alias.
        if (categoryKey === 'مسلسلات تركية مترجمة' && barePrefix('AR-TR-S').test(raw)) {
            raw = raw.replace(barePrefix('AR-TR-S'), 'TR'); category = 'TURKISH SERIES';
        } else if (['Séries TURQUES SUB-AR', 'مسلسلات تركية مترجمة عربي | Turkish Series Arabic Sub'].includes(categoryKey)) {
            category = 'TURKISH SERIES';
            // Only a redundant terminal marker; a preceding [FR]/[MULTI] stays.
            raw = raw.replace(/\s+\[SUB\]\s*$/, '');
        }
        if (['افلام تركية مدبلجة', 'مسلسلات تركية مدبلجة', 'يعرض الآن تركي مدبلج'].includes(categoryKey)
            && barePrefix('AR-TR-D').test(raw)) {
            raw = raw.replace(barePrefix('AR-TR-D'), 'AR-D'); category = 'ARABIC DUB';
        } else if (categoryKey === 'مسلسلات اجنبية قصيرة مدبلجة' && barePrefix('AR-EN-S-D').test(raw)) {
            raw = raw.replace(barePrefix('AR-EN-S-D'), 'AR-D'); category = 'ARABIC DUB';
        } else if (categoryKey === 'HINDI DUBBED (KOREAN)' && barePrefix('IN(?:-?KD)?').test(raw)) {
            category = 'HINDI DUB';
        } else if (categoryKey === 'INDIA EN DUBBED' && barePrefix('IN').test(raw)) {
            category = 'EN | DUB';
        } else if (['TURKSIH SERIES (SUB EN)', 'EN - ITALIAN SUB ENG'].includes(categoryKey) && barePrefix('EN').test(raw)
            && !/^\s*EN\s*[-–—|:]\s*EN\s*[-–—|:]/.test(raw)) {
            // Here EN belongs to SUB EN/ENG, not to the audio. Independent
            // release suffixes and other subtitle markers remain authoritative.
            raw = raw.replace(barePrefix('EN'), categoryKey.startsWith('TURKSIH') ? 'TR' : 'IT');
            category = categoryKey.startsWith('TURKSIH') ? 'TURKISH SERIES' : 'ITALIAN SERIES';
        } else if (categoryKey === 'ASIA MOVIES (MULTI-SUBS)' && /\(Cantonese ver\.\)\s*(?:(?:19|20)\d{2})?\s*$/i.test(raw)) {
            category = ''; raw = raw.replace(/\(Cantonese ver\.\)/i, '(Cantonese version)');
        } else if (categoryKey === 'AR★ أفلام كرتون للأطفال' && /مدبلج/.test(raw) && !RTL_SUB_RE.test(raw)) {
            category = 'ARABIC DUB';
        }
        // An explicit French declaration remains useful on these bounded
        // French MULTI shelves; it does not assert a second language or count.
        const declaredFrenchMulti = /^FR:\s*(?:FILMS\s*-\s*[^|:]+|Documentaires)\s*$/i.test(categoryKey)
            || categoryKey === 'FRANÇAIS';
        const providerPrefixMatch = raw.match(/^\s*([A-Z0-9]+(?:[._/+-][A-Z0-9]+){0,4})(?:\s*[-–—]\s+|\s+[-–—]\s*|\s*[|:]\s*)/)
            // Some suppliers separate a composite tag from its title with two
            // spaces. A plain title word followed by spaces is never a prefix.
            || raw.match(/^\s*([A-Z0-9]+(?:[._/+-][A-Z0-9]+){1,4})[ \t]{2,}/);
        const prefixMatch = providerPrefixMatch
            || raw.match(/^\s*[[(]([\p{L}\p{M}\d ./+-]{2,40})[\])]\s*/u);
        const prefix = prefixMatch?.[1] || '';
        // Audited EN-prefixed UFC releases are English declarations in the NL
        // market section. Suppress only this exact category's market token;
        // [EN], NL prefixes, other sports sections and suffix conflicts remain.
        const enNlUfcCategory = Boolean(providerPrefixMatch) && prefix === 'EN'
            && /^\s*NL\s*\|\s*UFC\s*$/i.test(category);
        // Explicit release suffixes / "Malayalam Dubbed" are annotations. Plain
        // title words ("Hindi Medium", "Johnny English", "It") are never scanned.
        // The supplier separator cannot also introduce a suffix: in "EN | Dutch"
        // or "SW | Dual", the entire remainder is a title, not a language tag.
        const title = prefixMatch ? raw.slice(prefixMatch[0].length) : raw;
        const withoutYear = title.replace(/\s*[[(]?(?:19|20)\d{2}[\])]?\s*$/, '').trim()
            // A technical release tail may follow a bracketed declaration.
            // Require that bracket boundary; never strip ordinary title prose.
            .replace(/([\])])(?:\s+(?:4K|8K|SD|HD|FHD|UHD|\d{3,4}p))+\s*$/i, '$1');
        const suffix = withoutYear.match(/(?:^|\s)([\p{L}\p{M}]{4,30})\s+\((?:Dubbed|Dub)\)\s*$/iu)?.[1]
            || withoutYear.match(/[[(]([\p{L}\p{M}\d ./+-]{2,40})[\])]\s*$/u)?.[1]
            || withoutYear.match(/\s[-–—|]\s*([A-Z]{2,3}|[\p{L}\p{M}]{4,30})\s*$/u)?.[1]
            || withoutYear.match(/(?:^|\s)([\p{L}\p{M}]{4,30})\s+(?:dubbed|dub|audio)\s*$/iu)?.[1]
            || withoutYear.match(/\b(?:dubbed|audio)\s+(?:in\s+)?([\p{L}\p{M}]{4,30})\s*$/iu)?.[1] || '';
        const inspect = (value, annotated = false, supplierPrefix = false) => {
            value = normalizeProviderDubbedCategory(value);
            if (annotated) value = value
                .replace(/^([\p{L}\p{M}]{4,30})(?:[- ]language)?\s+version$/iu, '$1')
                .replace(/^(?:19|20)\d{2}[-.]([\p{L}\p{M}]{4,30})$/u, '$1')
                // Audited release annotations, not general title/category words
                // or country aliases. The whole annotation must match.
                .replace(/^true\s+fr$/i, 'FR')
                .replace(/^nl-be$/i, 'NL')
                .replace(/^EX-YU$/i, 'EXYU')
                .replace(/^([\p{L}\p{M}]{2,30})\s+blu-ray$/iu, '$1');
            const originalTokens = stripDiacritics(value).normalize('NFC').split(/[^\p{L}\p{M}\d]+/u).filter(Boolean);
            const tokens = originalTokens.map(t => t.toLowerCase());
            const subOnly = (tokens.some(t => SUB_MARKERS.has(t) || /^(?:subtitled|vost\w*|sub(?:fr|en|es|ar|de|it|pt|nl|ru|hi))$/.test(t))
                || /sous[\s-]+titres/i.test(value) || RTL_SUB_RE.test(value))
                && !tokens.some(t => DUB_MARKERS.has(t));
            // Brackets alone are not proof of an annotation. For example, the
            // title warning "(NE CONVIENT PAS AUX ENFANTS)" is not Nepali audio.
            const annotationOnly = tokens.every(t => t === 'exyu' || Object.prototype.hasOwnProperty.call(VERSION_PROVIDER_LANGUAGE_TAGS, t)
                || SUB_MARKERS.has(t) || DUB_MARKERS.has(t)
                || (supplierPrefix && /^(?:af|vp|eg|ye|s|shr|as|sbus|sham|ma|alg|kh|doc|d|tn|xmas|pod|sh|anm|hara|li|ly|dz|ptv|do|ch|chr|irq|isl|bdy|kid|kids|hdr|dv|jo|jor|cam|dsc|pse|sus|geo|kd)$/.test(t))
                || /^(?:subtitled|vost\w*|sub(?:fr|en|es|ar|de|it|pt|nl|ru|hi)|multi|dual|bilingual|multiaudio|audio|in|4k|8k|sd|hd|fhd|uhd|\d{3,4}p)$/.test(t));
            if (annotated && !annotationOnly) return { subOnly, tags: [], multi: false, region: false };
            const codeIsBounded = token => new RegExp(`(?:^|[|:/\\[(])\\s*${token}(?:\\s*[-–—|:/\\])]|\\s*$)`, 'i').test(value);
            // EXYU is a regional catalogue marker, deliberately not a language
            // alias. Accept explicit annotations or a bounded category section,
            // never an ordinary title/category sentence containing the word.
            const region = tokens.includes('exyu') && (annotated || codeIsBounded('exyu')
                || /^\s*EXYU(?:\s+(?:MOVIES|FILMS|SERIES|SUBS?|SUBTITLES?|MULTI|4K|8K|SD|HD|FHD|UHD))*\s*$/i.test(value));
            const tags = [...new Set(tokens.map((t, i) => Object.prototype.hasOwnProperty.call(VERSION_PROVIDER_LANGUAGE_TAGS, t)
                && (t.length > 3 || tokens.length === 1 || (originalTokens[i] === originalTokens[i].toUpperCase() && (annotated || codeIsBounded(t))))
                ? VERSION_PROVIDER_LANGUAGE_TAGS[t] : null).filter(Boolean))];
            return { subOnly, tags, multi: tokens.some(t => /^(?:multi|dual|bilingual|multiaudio)$/.test(t)), region };
        };
        // An explicit supplier prefix may also carry non-language qualifiers
        // (AR-EG, AR-DOC-D, AF-EN). Only audited qualifiers are permitted here;
        // arbitrary title prose and the same qualifiers in brackets are not.
        // Only the matching bare market prefix is suppressed. [NL], another
        // language prefix and explicit suffixes keep their conflict semantics.
        const leading = inspect(nlHindiCategory && providerPrefixMatch && prefix === 'NL' ? '' : prefix,
            true, Boolean(providerPrefixMatch));
        const categorized = inspect(nlHindiCategory ? 'HINDI' : enNlUfcCategory ? 'UFC' : category);
        const trailing = inspect(suffix, true);
        // An explicit subtitle marker must not be bypassed by the other field.
        const audioBlocked = leading.subOnly || categorized.subOnly || trailing.subOnly
            || (!declaredFrenchMulti && (leading.multi || categorized.multi || trailing.multi))
            || /\b(?:vost\w*|subtitles?|subbed)\b/i.test(raw)
            // Standalone supplier markers only: المترجم can be the actual
            // movie title (The Translator), not a subtitle declaration.
            || /(?:^|[^\p{L}\p{M}])(?:مترجم|ترجمة|زیرنویس|زیرنویس‌دار)(?=$|[^\p{L}\p{M}])/u.test(raw);
        let tags = [...new Set([...leading.tags, ...categorized.tags, ...trailing.tags])];
        // A single Danish/Swedish/Norwegian tag refines the broader Nordic
        // category. Two specific languages, or a non-Nordic tag, still conflict.
        if (tags.length === 2 && tags.includes('nordic') && tags.some(tag => ['da', 'sv', 'no'].includes(tag))) {
            tags = tags.filter(tag => tag !== 'nordic');
        }
        // Conflicts/subtitle markers still prohibit an audio-language claim.
        // A regional marker can remain visible without making that claim.
        const region = leading.region || categorized.region || trailing.region || item.provider_label_language === 'exyu';
        const tag = !audioBlocked && tags.length === 1 ? tags[0] : region ? 'exyu' : null;
        if (!tag) return null;
        return tag;
    }

export const PROVIDER_CATALOG_LANGUAGES = Object.freeze([...new Set(Object.values(VERSION_PROVIDER_LANGUAGE_TAGS).filter(Boolean))]);
